507	// getMergeBase returns the merge base hash of two commits, or an error if they
508	// have no common ancestor.
509	func getMergeBase(ctx context.Context, repoPath, hashA, hashB string) (plumbing.Hash, error) {
510		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
511		defer cancel()
512	
513		cmd := exec.CommandContext(ctx, "git", "merge-base", hashA, hashB)
514		cmd.Dir = repoPath
515		output, err := cmd.Output()
516		if err != nil {
517			return plumbing.ZeroHash, fmt.Errorf("git merge-base failed: %w", err)
518		}
519	
520		return plumbing.NewHash(strings.TrimSpace(string(output))), nil
521	}
522	
523	// collectCommitsSince returns non-merge commits reachable from tip but not from
524	// exclude, ordered oldest-first in topological order.
525	func collectCommitsSince(ctx context.Context, repo *git.Repository, repoPath string, tip, exclude plumbing.Hash) ([]*object.Commit, error) {
526		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
527		defer cancel()
528	
529		// cherryPickOnto computes each commit's delta against its first parent, so
530		// replaying merge commits would incorrectly re-apply changes that arrived via
531		// non-first-parent history. Limit the replay set to non-merge commits.
532		cmd := exec.CommandContext(ctx, "git", "rev-list", "--reverse", "--topo-order", "--no-merges", exclude.String()+".."+tip.String())
533		cmd.Dir = repoPath
534		output, err := cmd.Output()
535		if err != nil {
536			return nil, fmt.Errorf("git rev-list failed: %w", err)
537		}
538	
539		lines := strings.Fields(string(output))
540		if len(lines) > MaxCommitTraversalDepth {
541			return nil, fmt.Errorf("commit chain exceeded %d commits; aborting rebase", MaxCommitTraversalDepth)
542		}
543	
544		commits := make([]*object.Commit, 0, len(lines))
545		for _, line := range lines {
546			hash := plumbing.NewHash(line)
547			commit, commitErr := repo.CommitObject(hash)
548			if commitErr != nil {
549				return nil, fmt.Errorf("failed to get commit %s: %w", hash, commitErr)
550			}
551			if len(commit.ParentHashes) > 1 {
552				continue
553			}
554			commits = append(commits, commit)
555		}
556	
557		return commits, nil
558	}
