560	// startProgressDots prints dots to w every second until the returned stop function
561	// is called. The stop function prints the given suffix and a newline.
562	func startProgressDots(w io.Writer) func(suffix string) {
563		done := make(chan struct{})
564		stopped := make(chan struct{})
565		go func() {
566			defer close(stopped)
567			ticker := time.NewTicker(time.Second)
568			defer ticker.Stop()
569			for {
570				select {
571				case <-done:
572					return
573				case <-ticker.C:
574					fmt.Fprint(w, ".")
575				}
576			}
577		}()
578		return func(suffix string) {
579			close(done)
580			<-stopped // Wait for goroutine to finish before writing suffix
581			fmt.Fprintln(w, suffix)
582		}
583	}
